import '../../../../core/network/api_client.dart'; import '../models/starting_baseline_model.dart';
class BaselineRemoteDataSource { const BaselineRemoteDataSource(this._api); final ApiClient _api; Future<StartingBaselineModel> trainerView(String traineeId) async=>StartingBaselineModel(Map<String,dynamic>.from(await _api.get<Map<String,dynamic>>('/trainer/trainees/$traineeId/starting-baseline'))); Future<Map<String,dynamic>> photoReadAccess(String traineeId,String photoId)=>_api.get<Map<String,dynamic>>('/trainer/trainees/$traineeId/starting-baseline/photos/$photoId/read-access'); }
